    /** `table[v] = bases[spec[3i] * 256 + (v xor inXor)] xor outXor` */
    private fun unpack(bases: IntArray, spec: IntArray, index: Int): IntArray {
        val base = spec[index * 3] * 256
        val inXor = spec[index * 3 + 1]
        val outXor = spec[index * 3 + 2]
        return IntArray(256) { v -> (bases[base + (v xor inXor)] xor outXor) and 0xFF }
    }

    /** The 160 Type-I tables: SubBytes through encoded bijections. */
    val typeI: Array<IntArray> by lazy { Array(160) { unpack(TYPE_I_BASES, TYPE_I_SPEC, it) } }

    /**
     * The 4 Type-II T-box tables: SubBytes and MixColumns combined.
     *
     * These are **32-bit** values, not bytes. Go declares
     * `var wbaesTypeII [4][256]uint32` and builds each entry by OR-ing four
     * independent byte lanes (spec triples `4k..4k+3` for table `k`):
     *
     *     t[k][v] |= uint32(bases[spec[n]][v ^ inXor[n]] ^ outXor[n]) << (8*lane)
     *
     * Building four *byte* tables instead collapses every entry to lane 0,
     * zeroing `cols[c] >> 8/16/24` -- 12 of the 16 state bytes per round. That
     * still yields a full-looking GP buffer and m3, so it is silent without the
     * end-to-end golden corpus.
     */
    val typeII: Array<IntArray> by lazy {
        Array(4) { k ->
            val lanes = Array(4) { lane -> unpack(TYPE_II_BASES, TYPE_II_SPEC, k * 4 + lane) }
            IntArray(256) { v ->
                lanes[0][v] or (lanes[1][v] shl 8) or (lanes[2][v] shl 16) or (lanes[3][v] shl 24)
            }
        }
    }

    /** Round-10 output decoding, one 256-byte bijection per position. */
    val outputDec: Array<IntArray> by lazy { Array(16) { unpack(OUTPUT_DEC_BASE, OUTPUT_DEC_SPEC, it) } }
}
